def transform(g):
    coords=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8]
    r0=min(r for r,c in coords); r1=max(r for r,c in coords)
    c0=min(c for r,c in coords); c1=max(c for r,c in coords)
    out=[]
    for r in range(r0,r1+1):
        row=[]
        rr=31-r
        for c in range(c0,c1+1):
            if rr < len(g) and c < len(g[0]) and g[rr][c]!=8:
                v=g[rr][c]
            elif rr<len(g) and 31-c < len(g[0]) and g[rr][31-c]!=8:
                v=g[rr][31-c]
            elif rr<len(g) and 29-c < len(g[0]) and g[rr][29-c]!=8:
                v=g[rr][29-c]
            else:
                v=g[rr][c] if rr<len(g) and c<len(g[0]) else 0
            row.append(v)
        out.append(row)
    return out
